/* eslint-disable no-undef */
import { Component, Element, Event, EventEmitter, h, Host, Listen, Prop } from '@stencil/core';
import { ChipMainColor, ChipSize, ChipVariant, Rel, Target } from '../../types';
import { verifyTarget } from '../../utils/link-helper';

/**
 * @slot default - default slot for the text content of the chip
 * @slot start - slot for displaying content on the inner left side of the chip
 * @slot end - slot for displaying content on the inner right side of the chip
 * @slot avatar - slot for displaying an avatar on the inner left side of the chip.
 */
@Component({
  tag: 'groupui-chip',
  styleUrl: 'chip.scss',
  shadow: { delegatesFocus: true },
})
export class Chip {
  /**
   * variant of the chip
   */
  @Prop({ reflect: true }) readonly variant: ChipVariant = 'primary';

  /**
   * size of the chip
   */
  @Prop({ reflect: true }) readonly size: ChipSize = 'm';

  /**
   * color of the chip
   */
  @Prop({ reflect: true }) readonly color: ChipMainColor = 'information';

  /**
   * disables the chip
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * URL that the hyperlink points to. Examples: https://www.volkswagen.de/ - tel:05361/12345 - mailto:john.doe@example.com - #anchor1
   */
  @Prop({ reflect: true }) readonly href: string;

  /**
   * where to display the linked URL. On target 'none' no target attribute will be set.
   */
  @Prop({ reflect: true }) readonly target: Target = 'self';

  /**
   * in which relation is the linked URL to the current page
   */
  @Prop({ reflect: true }) readonly rel: Rel;

  /**
   * to use chip in other components, disables tab, enter and space keyboard handling
   */
  @Prop({ reflect: true }) readonly embedded: boolean = false;

  /**
   * dispatched on end slot clicked
   */
  @Event() groupuiEndSlotClicked: EventEmitter<void>;

  @Element() host: HTMLElement;

  componentDidLoad() {
    if (!this.endSlotContent() || this.disabled) return;

    this.endSlotContent().addEventListener('click', (e) => {
      e.preventDefault();
      this.groupuiEndSlotClicked.emit();
    });
  }

  @Listen('click', { capture: true })
  captureClick(event) {
    if (this.disabled) {
      event.stopPropagation();
    }
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (!this.disabled && (event.code === 'Enter' || event.code === 'Space')) {
      if (this.embedded) {
        event.preventDefault();
        return;
      } else if (!this.href) {
        this.host.dispatchEvent(new window.Event('click', { bubbles: true }));
      } else {
        const linkItem = this.host.shadowRoot.querySelector('a');
        linkItem.click();
      }
      event.preventDefault();
    }
  }

  private onAvatarSlotChanged = () => {
    if (this.avatar()) {
      const avatarSize = this.size === 'm' ? 'xs' : 's';
      this.avatar().setAttribute('size', avatarSize);
    }
  };

  private avatar(): HTMLGroupuiAvatarElement {
    return this.host.querySelector('groupui-avatar');
  }

  private endSlotContent(): HTMLSlotElement {
    return this.host.querySelector('[slot="end"]');
  }

  render() {
    return (
      <Host>
        {this.href ? (
          <a
            tabIndex={this.disabled || this.embedded ? -1 : 0}
            href={this.disabled ? null : this.href}
            target={verifyTarget(this.target)}
            rel={this.rel}
          >
            <slot name="avatar" onSlotchange={this.onAvatarSlotChanged} aria-hidden="true" />
            <slot name="start" />
            <slot />
            <slot name="end" />
          </a>
        ) : (
          <button tabIndex={this.disabled || this.embedded ? -1 : 0} type="button">
            <slot name="avatar" onSlotchange={this.onAvatarSlotChanged} aria-hidden="true" />
            <slot name="start" />
            <slot />
            <slot name="end" />
          </button>
        )}
      </Host>
    );
  }
}
